#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 2005
#define NEG_INF (-1e18)

long long dp[MAXN][MAXN/2 + 2][2];
int A[MAXN];

int main() {
    int N;
    scanf("%d", &N);
    for (int i = 1; i <= N; i++) {
        scanf("%d", &A[i]);
    }

    int K = N / 2;

    // Initialize all to NEG_INF
    for (int i = 0; i <= N; i++)
        for (int j = 0; j <= K; j++) {
            dp[i][j][0] = (long long)NEG_INF;
            dp[i][j][1] = (long long)NEG_INF;
        }

    dp[0][0][0] = 0; // before any elements, 0 chosen, "not chosen" state

    for (int i = 1; i <= N; i++) {
        for (int j = 0; j <= K; j++) {
            // Don't choose element i
            long long best_prev = dp[i-1][j][0];
            if (dp[i-1][j][1] > best_prev) best_prev = dp[i-1][j][1];
            if (best_prev > (long long)NEG_INF)
                dp[i][j][0] = best_prev;

            // Choose element i (previous must not be chosen)
            if (j >= 1 && dp[i-1][j-1][0] > (long long)NEG_INF) {
                dp[i][j][1] = dp[i-1][j-1][0] + A[i];
            }
        }
    }

    long long ans = dp[N][K][0];
    if (dp[N][K][1] > ans) ans = dp[N][K][1];

    printf("%lld\n", ans);
    return 0;
}

