#define MAXN 200005

int max(int a, int b) {
    return a > b ? a : b;
}

int main() {
    int N;
    scanf("%d", &N);
    int A[MAXN];
    for (int i = 1; i <= N; i++) {
        scanf("%d", &A[i]);
    }

    int K = N / 2;
    // dp[i][j] for i from 0..N, j from 0..K
    int dp[MAXN][2];
    // We'll use two rows to save memory, but given N <= 200000, we can also use full table.
    // However, to be safe with memory we'll use rolling arrays.

    // Initialize with very small values
    for (int j = 0; j <= K; j++) {
        dp[0][j] = INT_MIN / 2;
    }
    dp[0][0] = 0;

    for (int i = 1; i <= N; i++) {
        for (int j = 0; j <= K; j++) {
            dp[i % 2][j] = dp[(i - 1) % 2][j];
            if (j >= 1) {
                int prev = (i >= 2) ? dp[(i - 2) % 2][j - 1] : 0;
                if (i >= 2 || j == 1) {
                    if (i >= 2) {
                        dp[i % 2][j] = max(dp[i % 2][j], prev + A[i]);
                    } else if (j == 1) {
                        dp[i % 2][j] = max(dp[i % 2][j], A[i]);
                    }
                }
            }
        }
    }

    printf("%d\n", dp[N % 2][K]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static inline ll maxll(ll a, ll b) {
    return a > b ? a : b;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc((N + 1) * sizeof(ll));
    for (int i = 1; i <= N; i++) scanf("%lld", &A[i]);

    int K = N / 2;
    const ll NEG = -(1LL << 60);

    /* dp0[j]: after current position, max sum choosing j elements, current not chosen
       dp1[j]: after current position, max sum choosing j elements, current chosen */
    ll *dp0 = (ll *)malloc((K + 1) * sizeof(ll));
    ll *dp1 = (ll *)malloc((K + 1) * sizeof(ll));
    ll *ndp0 = (ll *)malloc((K + 1) * sizeof(ll));
    ll *ndp1 = (ll *)malloc((K + 1) * sizeof(ll));

    for (int j = 0; j <= K; j++) dp0[j] = dp1[j] = NEG;
    dp0[0] = 0;

    for (int i = 1; i <= N; i++) {
        for (int j = 0; j <= K; j++) ndp0[j] = ndp1[j] = NEG;

        for (int j = 0; j <= K; j++) {
            /* Do not choose A[i] */
            ndp0[j] = maxll(ndp0[j], dp0[j]);
            ndp0[j] = maxll(ndp0[j], dp1[j]);

            /* Choose A[i] => previous must be not chosen */
            if (j + 1 <= K && dp0[j] != NEG) {
                ndp1[j + 1] = maxll(ndp1[j + 1], dp0[j] + A[i]);
            }
        }

        ll *tmp;
        tmp = dp0; dp0 = ndp0; ndp0 = tmp;
        tmp = dp1; dp1 = ndp1; ndp1 = tmp;
    }

    ll ans = maxll(dp0[K], dp1[K]);
    printf("%lld\n", ans);

    free(A);
    free(dp0);
    free(dp1);
    free(ndp0);
    free(ndp1);
    return 0;
}

