public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] A = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            A[i] = sc.nextInt();
        }

        int K = N / 2;

        // dp[j][last]: max sum having chosen j elements, last element chosen status
        // We'll use long to avoid overflow
        long NEG_INF = Long.MIN_VALUE / 2;

        // dp[i][j][0/1]
        // Use rolling array on i
        long[][] dp = new long[K + 1][2];
        for (long[] row : dp) Arrays.fill(row, NEG_INF);
        dp[0][0] = 0; // 0 elements chosen, last not chosen

        for (int i = 1; i <= N; i++) {
            long[][] ndp = new long[K + 1][2];
            for (long[] row : ndp) Arrays.fill(row, NEG_INF);

            for (int j = 0; j <= K; j++) {
                // Don't choose element i
                if (dp[j][0] != NEG_INF) {
                    ndp[j][0] = Math.max(ndp[j][0], dp[j][0]);
                }
                if (dp[j][1] != NEG_INF) {
                    ndp[j][0] = Math.max(ndp[j][0], dp[j][1]);
                }
                // Choose element i (only if previous was not chosen)
                if (j > 0 && dp[j-1][0] != NEG_INF) {
                    ndp[j][1] = Math.max(ndp[j][1], dp[j-1][0] + A[i]);
                }
            }

            dp = ndp;
        }

        long ans = Math.max(dp[K][0], dp[K][1]);
        System.out.println(ans);
    }
}

