            a[i] = sc.nextInt();
        }

        int k = n / 2;
        long[][] dp = new long[n + 1][k + 1];
        for (long[] row : dp) Arrays.fill(row, Long.MIN_VALUE / 2);
        dp[0][0] = 0;
        dp[1][0] = 0;
        if (k >= 1) dp[1][1] = a[1];

        for (int i = 2; i <= n; i++) {
            dp[i][0] = 0;
            for (int j = 1; j <= k; j++) {
                // skip a[i]
                dp[i][j] = dp[i - 1][j];
                // take a[i]
                if (j >= 1) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 2][j - 1] + a[i]);
                }
            }
        }

        System.out.println(dp[n][k]);
    }
