import java.io.*;
import java.util.*;

public class Main {
    static final long NEG = Long.MIN_VALUE / 4;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] A = new long[N + 1];
        for (int i = 1; i <= N; i++) A[i] = fs.nextLong();

        int K = N / 2; // exactly floor(N/2) elements

        // dp0[j]: max sum after processing current prefix, choosing j elements, current position not chosen
        // dp1[j]: max sum after processing current prefix, choosing j elements, current position chosen
        long[] dp0 = new long[K + 1];
        long[] dp1 = new long[K + 1];
        Arrays.fill(dp0, NEG);
        Arrays.fill(dp1, NEG);
        dp0[0] = 0;

        for (int i = 1; i <= N; i++) {
            long[] ndp0 = new long[K + 1];
            long[] ndp1 = new long[K + 1];
            Arrays.fill(ndp0, NEG);
            Arrays.fill(ndp1, NEG);

            for (int j = 0; j <= K; j++) {
                // Do not choose i
                ndp0[j] = Math.max(ndp0[j], dp0[j]);
                ndp0[j] = Math.max(ndp0[j], dp1[j]);

                // Choose i: previous must be not chosen
                if (j > 0 && dp0[j - 1] != NEG) {
                    ndp1[j] = Math.max(ndp1[j], dp0[j - 1] + A[i]);
                }
            }

            dp0 = ndp0;
            dp1 = ndp1;
        }

        long ans = Math.max(dp0[K], dp1[K]);
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

