int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    // We need to choose exactly K = N/2 elements, no two adjacent.
    int K = N / 2;

    // dp[i][j] = max sum using first i elements (i from 0..N), choosing j elements.
    // We'll use -inf for impossible states.
    const long long NEG_INF = -1e18;
    vector<vector<long long>> dp(N + 1, vector<long long>(K + 1, NEG_INF));
    dp[0][0] = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j <= K; j++) {
            if (dp[i][j] == NEG_INF) continue;
            // Skip element i+1
            dp[i+1][j] = max(dp[i+1][j], dp[i][j]);
            // Take element i+1, but only if we can (no constraint here yet)
            if (j + 1 <= K) {
                // We can only take it if the previous element (i) was not taken.
                // In our DP, we don't directly track that. We need a different approach.
            }
        }
    }

    // The above simple DP doesn't enforce non-adjacent constraint correctly.
    // We need a state that knows whether previous element was taken.

    // Let's redefine: dp[i][j][t] where t=0 means A[i] not taken, t=1 means taken.
    // i from 1..N.
    vector<vector<vector<long long>>> dp2(N+1, vector<vector<long long>>(K+1, vector<long long>(2, NEG_INF)));
    dp2[0][0][0] = 0; // before first element, not taken

    for (int i = 0; i < N; i++) {
        for (int j = 0; j <= K; j++) {
            for (int taken = 0; taken < 2; taken++) {
                if (dp2[i][j][taken] == NEG_INF) continue;
                // Skip A[i+1]
                dp2[i+1][j][0] = max(dp2[i+1][j][0], dp2[i][j][taken]);
                // Take A[i+1] only if previous not taken
                if (taken == 0 && j + 1 <= K) {
                    dp2[i+1][j+1][1] = max(dp2[i+1][j+1][1], dp2[i][j][taken] + A[i]);
                }
            }
        }
    }

    long long ans = NEG_INF;
    for (int t = 0; t < 2; t++) {
        ans = max(ans, dp2[N][K][t]);
    }
    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;

    int k = n / 2;

    // WQS binary search
    // For penalty p, compute max sum - p*count and the count achieved
    auto solve = [&](long long p) -> pair<long long, int> {
        // dp[0] = (value, count) not taking current
        // dp[1] = (value, count) taking current
        long long v0 = 0, v1 = a[0] - p;
        int c0 = 0, c1 = 1;
        for (int i = 1; i < n; i++) {
            long long nv0, nv1;
            int nc0, nc1;
            // not take i: best of v0, v1
            if (v0 >= v1) { nv0 = v0; nc0 = c0; }
            else { nv0 = v1; nc0 = c1; }
            // take i: must come from v0 (not taking i-1)
            nv1 = v0 + a[i] - p; nc1 = c0 + 1;
            v0 = nv0; c0 = nc0;
            v1 = nv1; c1 = nc1;
        }
        if (v0 >= v1) return {v0, c0};
        return {v1, c1};
    };

    long long lo = -1e9, hi = 1e9;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        auto [val, cnt] = solve(mid);
        if (cnt <= k) hi = mid;
        else lo = mid + 1;
    }
    auto [val, cnt] = solve(lo);
    cout << val + lo * k << endl;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N + 1);
    for (int i = 1; i <= N; ++i) cin >> A[i];

    int K = N / 2; // must choose exactly K elements

    const long long NEG = -(1LL << 60);

    // dp0[j]: after processing current prefix, max sum choosing j elements,
    //         and current position is NOT chosen
    // dp1[j]: after processing current prefix, max sum choosing j elements,
    //         and current position IS chosen
    vector<long long> dp0(K + 1, NEG), dp1(K + 1, NEG);
    dp0[0] = 0;

    for (int i = 1; i <= N; ++i) {
        vector<long long> ndp0(K + 1, NEG), ndp1(K + 1, NEG);

        for (int j = 0; j <= K; ++j) {
            // Don't choose i
            ndp0[j] = max(ndp0[j], max(dp0[j], dp1[j]));

            // Choose i: previous must be not chosen
            if (j > 0 && dp0[j - 1] != NEG) {
                ndp1[j] = max(ndp1[j], dp0[j - 1] + A[i]);
            }
        }

        dp0.swap(ndp0);
        dp1.swap(ndp1);
    }

    cout << max(dp0[K], dp1[K]) << '\n';
    return 0;
}
